package com.lagalarm;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class LagAlarmLayoutTest
{
    @Test public void staysInsideChatInFixedResizableAndMovedLayouts()
    {
        Rectangle[] canvases = {new Rectangle(765, 503), new Rectangle(1200, 800), new Rectangle(1200, 800)};
        Rectangle[] chats = {new Rectangle(0, 338, 519, 165), new Rectangle(0, 635, 519, 165), new Rectangle(240, 570, 600, 190)};
        for (int i = 0; i < chats.length; i++)
        {
            Rectangle warning = LagAlarmPainter.warningBounds(canvases[i].width, canvases[i].height, chats[i]);
            assertTrue(canvases[i].contains(warning));
            assertTrue("Keep the game view unobstructed", chats[i].contains(warning));
            assertTrue("Follow the chatbox, not the canvas center", Math.abs(warning.getCenterX() - chats[i].getCenterX()) <= 1);
            assertTrue(Math.abs(warning.getCenterY() - chats[i].getCenterY()) <= 1);
        }
    }

    @Test public void painterRejectsInvalidAreas()
    {
        assertNull(LagAlarmPainter.warningBounds(1200, 800, null));
        assertNull(LagAlarmPainter.warningBounds(1200, 800, new Rectangle(1800, 1200, 519, 165)));
        assertNull(LagAlarmPainter.warningBounds(1200, 800, new Rectangle(0, 0, 0, 0)));
    }

    @Test public void absentOrOffscreenWidgetsUseTheUsualChatAreaOnTheCurrentCanvas()
    {
        Rectangle[] missing = {null, new Rectangle(1800, 1200, 519, 165), new Rectangle(0, 0, 0, 0)};
        Rectangle[] canvases = {new Rectangle(765, 503), new Rectangle(1200, 800)};
        for (Rectangle canvas : canvases)
        {
            for (Rectangle bounds : missing)
            {
                Rectangle area = LagAlarmPainter.chatboxArea(canvas.width, canvas.height, bounds, null);
                assertEquals(new Rectangle(0, canvas.height - 165, 519, 165), area);
                assertTrue(area.contains(LagAlarmPainter.warningBounds(canvas.width, canvas.height, area)));
            }
        }
    }

    @Test public void hiddenChatRetainsItsGeometryAndCollapsedControlsRestoreTheFootprint()
    {
        Rectangle full = new Rectangle(240, 570, 600, 190);
        Rectangle controls = new Rectangle(240, 735, 600, 25);
        // Geometry is deliberately independent of widget visibility, including hidden-at-startup.
        assertEquals(full, LagAlarmPainter.chatboxArea(1200, 800, full, controls));
        Rectangle expected = new Rectangle(240, 595, 600, 165);
        assertEquals(expected, LagAlarmPainter.chatboxArea(1200, 800, null, controls));
        assertEquals(expected, LagAlarmPainter.chatboxArea(1200, 800, controls, null));
        assertEquals(100, LagAlarmPainter.warningBounds(1200, 800, expected).height);
    }

    @Test public void collapsedAndPartlyOffscreenChatKeepsWarningInsideVisibleChat()
    {
        Rectangle[] chats = {new Rectangle(0, 775, 519, 25), new Rectangle(-200, 300, 519, 165),
            new Rectangle(900, 700, 519, 165)};
        Rectangle canvas = new Rectangle(1200, 800);
        for (Rectangle chat : chats)
        {
            Rectangle warning = LagAlarmPainter.warningBounds(canvas.width, canvas.height, chat);
            assertNotNull(warning);
            assertTrue(chat.intersection(canvas).contains(warning));
        }
    }

    @Test public void paintingIncludingPulseAndShadowNeverSpillsOutsideChat()
    {
        Rectangle[] chats = {new Rectangle(0, 338, 519, 165), new Rectangle(0, 775, 519, 25), null};
        LagDetector.Snapshot snapshot = new LagDetector.Snapshot(LagDetector.Mode.MONITORING,
            LagDetector.Reason.TICK_STALL, 301, 1800, -1, false);
        for (Rectangle chat : chats)
        {
            BufferedImage image = new BufferedImage(1200, 800, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = image.createGraphics();
            try
            {
                LagAlarmPainter.paint(g, 1200, 800, chat, snapshot, Color.ORANGE, true, 400);
            }
            finally { g.dispose(); }
            int painted = 0;
            for (int y = 0; y < image.getHeight(); y++)
            {
                for (int x = 0; x < image.getWidth(); x++)
                {
                    if (image.getRGB(x, y) != 0)
                    {
                        assertTrue("All visual effects must remain within chat", chat != null && chat.contains(x, y));
                        painted++;
                    }
                }
            }
            if (chat != null) { assertTrue("Visible chat should receive an alert", painted > 0); }
        }
    }
}

package com.lagalarm;

import com.sun.management.OperatingSystemMXBean;
import java.io.PrintWriter;
import java.lang.management.ManagementFactory;
import java.net.Inet4Address;
import java.net.InetAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.http.api.worlds.World;

/** Development-only harness. Does not log in, touch game inputs, or change network settings. */
public class LagAlarmBenchmark
{
    public static void main(String[] args) throws Exception
    {
        if (args.length < 5) { throw new IllegalArgumentException("host seconds interval-ms deadline-ms output-directory"); }
        String host = args[0];
        int seconds = Math.max(5, Math.min(300, Integer.parseInt(args[1])));
        int interval = Math.max(100, Integer.parseInt(args[2]));
        int deadline = Math.max(100, Integer.parseInt(args[3]));
        boolean automatic = args.length > 5 && "automatic".equals(args[5]);
        Path output = Path.of(args[4]);
        Files.createDirectories(output);
        InetAddress address = InetAddress.getByName(host);
        if (!(address instanceof Inet4Address)) { throw new IllegalArgumentException("Select an IPv4 endpoint"); }
        // Resolve once before timing: separate DNS/bootstrap cost from steady-state probes.
        World world = World.builder().address(address.getHostAddress()).id(301).build();
        Ping.ping(world, false); // Warm native libraries and ICMP path outside the measurement.
        LagDetector detector = new LagDetector();
        detector.configure(automatic ? LagDetector.Settings.automatic()
            : new LagDetector.Settings(1500, 0, 3000, true, 400, 2, true, deadline, 20, 20));
        ProbePacer pacer = new ProbePacer();
        long origin = LagAlarmPlugin.now();
        detector.loggedIn(301, origin);
        detector.tick(origin);
        OperatingSystemMXBean operatingSystem = (OperatingSystemMXBean) ManagementFactory.getOperatingSystemMXBean();
        long cpuStart = operatingSystem.getProcessCpuTime();
        long wallStart = System.nanoTime();
        AtomicInteger checks = new AtomicInteger();
        AtomicLong maxCheck = new AtomicLong();
        AtomicInteger alarms = new AtomicInteger();
        List<Integer> roundTrips = Collections.synchronizedList(new ArrayList<>());
        List<Integer> watchdogGaps = Collections.synchronizedList(new ArrayList<>());
        AtomicLong previousCheck = new AtomicLong();
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(3);
        try (PrintWriter csv = new PrintWriter(Files.newBufferedWriter(output.resolve("probes.csv"), StandardCharsets.UTF_8)))
        {
            csv.println("start_epoch_ms,start_elapsed_ms,end_elapsed_ms,call_duration_ms,rtt_ms,success");
            ScheduledFuture<?> ticks = executor.scheduleAtFixedRate(() -> detector.tick(LagAlarmPlugin.now()), 600, 600, TimeUnit.MILLISECONDS);
            ScheduledFuture<?> watch = executor.scheduleWithFixedDelay(() ->
            {
                long started = System.nanoTime();
                long previous = previousCheck.getAndSet(started);
                if (previous != 0) { watchdogGaps.add((int) ((started - previous) / 1000)); }
                if (detector.evaluate(LagAlarmPlugin.now()).isAlarm()) { alarms.incrementAndGet(); }
                maxCheck.accumulateAndGet(System.nanoTime() - started, Math::max);
                checks.incrementAndGet();
            }, 0, 25, TimeUnit.MILLISECONDS);
            ScheduledFuture<?> probes = executor.scheduleWithFixedDelay(() ->
            {
                long start = LagAlarmPlugin.now();
                long epoch = System.currentTimeMillis();
                LagDetector.Probe request = detector.probe();
                if (automatic && !pacer.ready(request, start)) { return; }
                if (!detector.beginProbe(request, start)) { throw new IllegalStateException("Overlapping probe"); }
                int result = Ping.ping(world, false);
                long end = LagAlarmPlugin.now();
                detector.ping(request, result, end);
                if (automatic) { pacer.finished(request, end, detector.probeDelay()); }
                roundTrips.add(result);
                csv.printf(Locale.ROOT, "%d,%d,%d,%d,%d,%s%n", epoch, start - origin, end - origin, end - start, result, result >= 0);
                csv.flush();
            }, 0, automatic ? 25 : interval, TimeUnit.MILLISECONDS);
            // The harness has an explicit bounded duration; the plugin never blocks this way.
            executor.schedule(() -> {}, seconds, TimeUnit.SECONDS).get(seconds + 5L, TimeUnit.SECONDS);
            probes.cancel(false);
            ticks.cancel(false);
            watch.cancel(false);
            executor.shutdown();
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) { executor.shutdownNow(); }
            double elapsed = (System.nanoTime() - wallStart) / 1e9;
            double cpuMs = (operatingSystem.getProcessCpuTime() - cpuStart) / 1e6;
            List<Integer> successful = new ArrayList<>();
            synchronized (roundTrips) { for (int value : roundTrips) { if (value >= 0) { successful.add(value); } } }
            Collections.sort(successful);
            Collections.sort(watchdogGaps);
            int count = roundTrips.size();
            int replies = successful.size();
            // Each minimum IPv4 echo packet: 20-byte IP header + 8-byte ICMP header + 11-byte payload.
            int estimatedIpBytes = 39 * (count + replies);
            String report = String.format(Locale.ROOT,
                "Host: %s (%s)%nElapsed: %.3f s%nPolicy: %s%nCurrent base pause: %d ms%nCurrent deadline: %d ms%n"
                + "Completed attempts: %d%nSuccessful replies: %d%nFailed attempts: %d%n"
                + "RTT p50/p95/p99: %d / %d / %d ms%n"
                + "Watchdog evaluations: %d%nMaximum evaluation cost: %.3f ms%n"
                + "Actual watchdog gap p50/p95/p99: %.3f / %.3f / %.3f ms (requested 25 ms)%n"
                + "Alarmed evaluations: %d (synthetic healthy game ticks)%n"
                + "Process CPU: %.3f ms (%.4f%% of one logical core over this interval)%n"
                + "Estimated minimum IPv4 bytes: %d (%.2f B/s)%n"
                + "Traffic above is calculated from attempts/replies, NOT packet-capture measured bytes.%n"
                + "Warmup, DNS, Ethernet/Wi-Fi headers, tunneling, driver overhead, and failed sends are excluded.%n"
                + "CPU includes this harness, CSV writes, JIT/GC and native calls; this is not a full-client overhead measurement.%n",
                host, address.getHostAddress(), elapsed, automatic ? "automatic with pacing jitter" : "fixed benchmark override",
                automatic ? detector.probeDelay() : interval, automatic ? detector.evaluate(LagAlarmPlugin.now()).deadlineMs : deadline,
                count, replies, count - replies,
                percentile(successful, 0.50), percentile(successful, 0.95), percentile(successful, 0.99),
                checks.get(), maxCheck.get() / 1e6,
                percentile(watchdogGaps, .50) / 1000.0, percentile(watchdogGaps, .95) / 1000.0,
                percentile(watchdogGaps, .99) / 1000.0, alarms.get(), cpuMs, cpuMs / (elapsed * 10),
                estimatedIpBytes, estimatedIpBytes / elapsed);
            Files.writeString(output.resolve("live-summary.txt"), report, StandardCharsets.UTF_8);
            System.out.print(report);
        }
        finally { executor.shutdownNow(); }
    }

    private static int percentile(List<Integer> values, double percentile)
    {
        return values.isEmpty() ? -1 : values.get(Math.max(0, (int) Math.ceil(values.size() * percentile) - 1));
    }
}

package com.lagalarm;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/** Uses the production painter with illustrative chat bounds, without interacting with RuneScape. */
public class LagAlarmPreview
{
    public static void main(String[] args) throws Exception
    {
        File directory = new File(args[0]);
        if (!directory.isDirectory() && !directory.mkdirs()) { throw new IllegalStateException("Cannot create preview directory"); }
        render(directory, "fixed", 765, 503, new Rectangle(0, 338, 519, 165), VisualAlert.BANNER_AND_BORDER);
        render(directory, "resizable", 1200, 800, new Rectangle(0, 635, 519, 165), VisualAlert.BANNER_AND_BORDER);
        render(directory, "moved-chat", 1200, 800, new Rectangle(240, 570, 600, 190), VisualAlert.BANNER);
        render(directory, "hidden-chat", 1200, 800, null, VisualAlert.BANNER_AND_BORDER);
        render(directory, "fixed-hide-chat", 765, 503, new Rectangle(0, 338, 519, 165), VisualAlert.BANNER_AND_BORDER, false);
        render(directory, "collapsed-chat", 1200, 800, new Rectangle(0, 775, 519, 25), VisualAlert.BANNER);
        render(directory, "visual-off", 765, 503, new Rectangle(0, 338, 519, 165), VisualAlert.OFF);
    }

    private static void render(File directory, String name, int width, int height, Rectangle chatbox, VisualAlert visual) throws Exception
    {
        render(directory, name, width, height, chatbox, visual, true);
    }

    private static void render(File directory, String name, int width, int height, Rectangle chatbox, VisualAlert visual,
        boolean chatVisible) throws Exception
    {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(37, 43, 49));
        g.fillRect(0, 0, width, height);
        g.setColor(new Color(57, 64, 69));
        for (int x = 0; x < width; x += 32) { g.drawLine(x, 0, x, height); }
        for (int y = 0; y < height; y += 32) { g.drawLine(0, y, width, y); }
        if (chatbox != null && chatVisible)
        {
            g.setColor(new Color(62, 57, 48));
            g.fill(chatbox);
            g.setColor(new Color(141, 130, 112));
            g.draw(chatbox);
            g.drawString("CHATBOX - illustrative bounds", chatbox.x + 12, chatbox.y + 18);
        }
        if (visual != VisualAlert.OFF)
        {
            LagDetector.Snapshot snapshot = new LagDetector.Snapshot(LagDetector.Mode.MONITORING,
                LagDetector.Reason.TICK_STALL, 301, 1800, -1, false);
            Rectangle area = LagAlarmPainter.chatboxArea(width, height, chatbox, null);
            LagAlarmPainter.paint(g, width, height, area, snapshot, new Color(255, 176, 64),
                visual == VisualAlert.BANNER_AND_BORDER, 400);
        }
        g.setColor(new Color(165, 174, 180));
        g.drawString("Lag Alarm / " + name + " / layout preview, not a game screenshot", 22, 24);
        g.dispose();
        ImageIO.write(image, "png", new File(directory, "chatbox-" + name + ".png"));
    }
}

package com.lagalarm;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Locale;
import java.util.Random;

/** Deterministic simulated time and inputs; never changes the real network. */
public class LagAlarmSimulation
{
    public static void main(String[] args) throws Exception
    {
        Path output = Path.of(args[0]);
        Files.createDirectories(output);
        StringBuilder report = new StringBuilder("SIMULATED detection latency; not a measurement of your network.\n");
        report.append("1000 randomized outage phases per profile; seed 20261006; watchdog 25 ms.\n");
        report.append("Baseline inputs: 0 ms RTT / 0% probe loss. Complete outage begins after calibration.\n");
        report.append("profile,mean_ms,p50_ms,p95_ms,p99_ms,min_ms,max_ms\n");
        for (int mode = 0; mode < 4; mode++)
        {
            int[] values = new int[1000];
            Random random = new Random(20261006);
            for (int i = 0; i < values.length; i++)
            {
                values[i] = trial(mode, 6000 + random.nextInt(3000));
            }
            Arrays.sort(values);
            double mean = Arrays.stream(values).average().orElseThrow();
            String profile = new String[]{"passive-1500", "fixed-pause500-deadline600", "fixed-pause250-deadline200", "automatic-current-default"}[mode];
            report.append(String.format(Locale.ROOT, "%s,%.2f,%d,%d,%d,%d,%d%n", profile, mean,
                values[499], values[949], values[989], values[0], values[999]));
        }
        report.append("Fast warning is possible probe delay, not confirmed game-packet loss.\n");
        report.append("Zero RTT is a synthetic lower bound, not a normal internet latency claim.\n");
        Files.writeString(output.resolve("simulation.csv"), report, StandardCharsets.UTF_8);
        System.out.print(report);
    }

    private static int trial(int mode, int outage)
    {
        boolean active = mode != 0;
        int interval = mode == 2 ? 250 : 500;
        int deadline = mode == 2 ? 200 : 600;
        LagDetector detector = new LagDetector();
        detector.configure(new LagDetector.Settings(1500, 0, 3000, active, 400, 2, true, deadline, 20, 20));
        if (mode == 3) { detector.configure(LagDetector.Settings.automatic()); }
        detector.loggedIn(301, 0);
        int nextProbe = 0;
        LagDetector.Probe pending = null;
        int completeAt = 0;
        for (int now = 0; now <= outage + 5000; now++)
        {
            if (now < outage && now % 600 == 0) { detector.tick(now); }
            if (active)
            {
                if (pending != null && now >= completeAt)
                {
                    detector.ping(pending, -1, now);
                    pending = null;
                    nextProbe = now + (mode == 3 ? detector.probeDelay() : interval);
                }
                if (pending == null && now >= nextProbe)
                {
                    LagDetector.Probe request = detector.probe();
                    detector.beginProbe(request, now);
                    if (now < outage)
                    {
                        detector.ping(request, 0, now);
                        nextProbe = now + (mode == 3 ? detector.probeDelay() : interval);
                    }
                    else { pending = request; completeAt = now + 2000; }
                }
            }
            if (now % 25 == 0 && detector.evaluate(now).isAlarm())
            {
                if (now < outage) { throw new AssertionError("False alarm during zero-lag baseline"); }
                return now - outage;
            }
        }
        throw new AssertionError("Outage went undetected");
    }
}

package com.lagalarm;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class LagDetectorTest
{
    private LagDetector detector;

    @Before public void setUp()
    {
        detector = new LagDetector();
        detector.configure(new LagDetector.Settings(1500, 0, 3000, true, 400));
        detector.loggedIn(301, 0);
        detector.tick(0);
    }

    @Test public void detectsStallWithoutAnyFurtherGameEvents()
    {
        assertFalse(detector.evaluate(1499).isAlarm());
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(1500).reason);
        assertEquals(1500, detector.evaluate(1500).tickAgeMs);
    }

    @Test public void normalTicksAndModestJitterDoNotAlarm()
    {
        for (long time : new long[]{600, 1210, 1830, 2800, 3400, 4000})
        {
            detector.tick(time);
            assertFalse(detector.evaluate(time + 100).isAlarm());
        }
    }

    @Test public void recoversOnlyAfterTwoNormallySpacedIntervals()
    {
        assertTrue(detector.evaluate(1600).isAlarm());
        detector.tick(2000);
        assertEquals(LagDetector.Reason.RECOVERING, detector.evaluate(2000).reason);
        detector.tick(2600);
        assertTrue(detector.evaluate(2600).isAlarm());
        detector.tick(3200);
        assertFalse(detector.evaluate(3200).isAlarm());
    }

    @Test public void queuedTickBurstDoesNotClearAlarm()
    {
        detector.evaluate(1600);
        detector.tick(2000);
        detector.tick(2001);
        detector.tick(2002);
        assertTrue(detector.evaluate(2002).isAlarm());
        detector.tick(2602);
        detector.tick(3202);
        assertFalse(detector.evaluate(3202).isAlarm());
    }

    @Test public void noticesLongTickGapEvenIfWatchdogWasPaused()
    {
        detector.tick(3000);
        assertEquals(LagDetector.Reason.RECOVERING, detector.evaluate(3000).reason);
    }

    @Test public void loginGraceIsBoundedEvenIfNoFirstTickArrives()
    {
        detector.stop();
        detector.configure(new LagDetector.Settings(1500, 3000, 3000, false, 400));
        detector.loggedIn(301, 500);
        assertFalse(detector.evaluate(3499).isAlarm());
        assertTrue(detector.evaluate(3499).warmingUp);
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(3500).reason);
    }

    @Test public void loadingHasBoundedGrace()
    {
        detector.loading(600);
        detector.loading(1000); // Repeated state events must not extend the deadline.
        assertFalse(detector.evaluate(3599).isAlarm());
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(3600).reason);
    }

    @Test public void normalLoadingThenReturnDoesNotImmediatelyAlarm()
    {
        detector.loading(600);
        detector.loggedIn(301, 2500);
        assertFalse(detector.evaluate(2500).isAlarm());
        detector.tick(2900);
        assertFalse(detector.evaluate(3000).isAlarm());
    }

    @Test public void loadingDoesNotHideAnExistingAlarm()
    {
        detector.evaluate(1600);
        detector.loading(1700);
        assertTrue(detector.evaluate(1800).isAlarm());
    }

    @Test public void connectionLostSuppressesAlarmAndReconnectGetsFreshGrace()
    {
        detector.configure(new LagDetector.Settings(1500, 3000, 3000, false, 400));
        detector.stop();
        detector.loggedIn(301, 0);
        assertTrue(detector.evaluate(3100).isAlarm());
        detector.connectionLost();
        assertFalse(detector.evaluate(3200).isAlarm());
        assertNull(detector.probe());
        detector.loggedIn(301, 5000);
        assertFalse(detector.evaluate(7999).isAlarm());
        assertTrue(detector.evaluate(7999).warmingUp);
        detector.tick(8000);
        assertFalse(detector.evaluate(8000).isAlarm());
    }

    @Test public void logoutClearsAllAlarmsAndStopsProbes()
    {
        detector.evaluate(1500);
        detector.test(1500);
        detector.stop();
        assertFalse(detector.evaluate(10000).isAlarm());
        assertEquals(LagDetector.Mode.IDLE, detector.evaluate(10000).mode);
        assertNull(detector.probe());
    }

    @Test public void delayedProbeFromOldWorldCannotPolluteNewWorld()
    {
        LagDetector.Probe old = detector.probe();
        detector.stop();
        detector.loggedIn(302, 1000);
        detector.ping(old, 800, 1100);
        detector.ping(old, 800, 1200);
        assertEquals(-1, detector.evaluate(1200).pingMs);
        assertFalse(detector.evaluate(1200).isAlarm());
    }

    @Test public void sameWorldRelogAlsoInvalidatesInFlightPing()
    {
        LagDetector.Probe old = detector.probe();
        detector.stop();
        detector.loggedIn(301, 1000);
        detector.ping(old, 800, 1100);
        assertEquals(-1, detector.evaluate(1100).pingMs);
    }

    @Test public void oneHighPingDoesNotAlarmButTwoDo()
    {
        detector.ping(detector.probe(), 400, 100);
        assertFalse(detector.evaluate(100).isAlarm());
        detector.tick(600);
        detector.ping(detector.probe(), 450, 1100);
        assertEquals(LagDetector.Reason.HIGH_PING, detector.evaluate(1100).reason);
    }

    @Test public void healthyPingResetsConsecutiveHighSamples()
    {
        detector.ping(detector.probe(), 500, 100);
        detector.ping(detector.probe(), 50, 200);
        detector.ping(detector.probe(), 500, 300);
        assertFalse(detector.evaluate(300).isAlarm());
    }

    @Test public void blockedPingAloneNeverAlarms()
    {
        for (int i = 1; i <= 10; i++)
        {
            detector.tick(i * 600);
            detector.ping(detector.probe(), -1, i * 600);
            assertFalse(detector.evaluate(i * 600).isAlarm());
        }
        assertEquals(-1, detector.evaluate(6000).pingMs);
    }

    @Test public void failedPingBreaksTheHighPingSequence()
    {
        detector.ping(detector.probe(), 700, 100);
        detector.ping(detector.probe(), -1, 200);
        detector.ping(detector.probe(), 700, 300);
        assertFalse(detector.evaluate(300).isAlarm());
    }

    @Test public void disablingPingsInvalidatesPendingResult()
    {
        LagDetector.Probe pending = detector.probe();
        detector.configure(new LagDetector.Settings(1500, 0, 3000, false, 400));
        detector.ping(pending, 900, 100);
        assertNull(detector.probe());
        assertEquals(-1, detector.evaluate(100).pingMs);
    }

    @Test public void staleHighPingExpiresInsteadOfAlarmingForever()
    {
        detector.ping(detector.probe(), 800, 100);
        detector.ping(detector.probe(), 800, 200);
        assertTrue(detector.evaluate(200).isAlarm());
        for (int i = 1; i <= 12; i++)
        {
            detector.tick(i * 600);
            detector.evaluate(i * 600);
        }
        assertFalse(detector.evaluate(7200).isAlarm());
        assertEquals(-1, detector.evaluate(7200).pingMs);
    }

    @Test public void widelySeparatedSamplesDoNotCountAsConsecutive()
    {
        detector.ping(detector.probe(), 800, 100);
        for (int i = 1; i <= 10; i++) { detector.tick(i * 600); }
        detector.ping(detector.probe(), 800, 6100);
        assertFalse(detector.evaluate(6100).isAlarm());
    }

    @Test public void tickStallTakesPriorityOverPing()
    {
        detector.ping(detector.probe(), 800, 100);
        detector.ping(detector.probe(), 800, 200);
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(1500).reason);
    }

    @Test public void testAlarmExpiresAndDoesNotMaskRealLag()
    {
        detector.test(100);
        assertEquals(LagDetector.Reason.TEST, detector.evaluate(100).reason);
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(1600).reason);
        for (int i = 3; i <= 9; i++) { detector.tick(i * 600); }
        assertFalse(detector.evaluate(5400).isAlarm());
    }

    @Test public void defaultPassiveConfigurationDoesNotRequestNetworkIo()
    {
        LagDetector passive = new LagDetector();
        passive.loggedIn(301, 0);
        assertNull(passive.probe());
    }

    @Test public void recoveryOfPingNeedsTwoHealthyProbesAndStableTicks()
    {
        detector.ping(detector.probe(), 800, 100);
        detector.ping(detector.probe(), 800, 200);
        detector.evaluate(200);
        detector.tick(600);
        detector.ping(detector.probe(), 50, 700);
        assertEquals(LagDetector.Reason.HIGH_PING, detector.evaluate(700).reason);
        detector.tick(1200);
        detector.ping(detector.probe(), 50, 1300);
        assertTrue(detector.evaluate(1300).isAlarm());
        detector.tick(1800);
        assertFalse(detector.evaluate(1800).isAlarm());
    }

    private void fastSettings(int deadline, int confirmations, int window, int failures)
    {
        detector.configure(new LagDetector.Settings(1500, 0, 3000, true, 400,
            confirmations, true, deadline, failures, window));
    }

    private void calibrate()
    {
        detector.ping(detector.probe(), 25, 100);
        detector.ping(detector.probe(), 25, 200);
        detector.ping(detector.probe(), 25, 300);
    }

    @Test public void earlyWarningDoesNotWaitForBlockingPingToReturn()
    {
        fastSettings(200, 2, 20, 20);
        calibrate();
        assertTrue(detector.beginProbe(detector.probe(), 400));
        assertFalse(detector.evaluate(599).isAlarm());
        assertEquals(LagDetector.Reason.PROBE_DELAY, detector.evaluate(600).reason);
    }

    @Test public void unsupportedPingCannotArmEarlyWarningsOrFailureRate()
    {
        fastSettings(200, 2, 5, 1);
        for (int i = 1; i < 20; i++)
        {
            long time = i * 600;
            detector.tick(time);
            LagDetector.Probe request = detector.probe();
            detector.beginProbe(request, time);
            assertFalse(detector.evaluate(time + 300).isAlarm());
            detector.ping(request, -1, time + 400);
            assertFalse(detector.evaluate(time + 400).isAlarm());
        }
    }

    @Test public void onlyOneProbeCanBeOutstanding()
    {
        assertTrue(detector.beginProbe(detector.probe(), 100));
        assertFalse(detector.beginProbe(detector.probe(), 200));
    }

    @Test public void hopInvalidatesOutstandingDeadline()
    {
        fastSettings(200, 2, 20, 20);
        calibrate();
        detector.beginProbe(detector.probe(), 400);
        detector.stop();
        detector.loggedIn(302, 500);
        assertFalse(detector.evaluate(1000).isAlarm());
    }

    @Test public void failureRateRequiresFullWindowAndWorkingIcmp()
    {
        fastSettings(200, 2, 5, 20);
        calibrate();
        detector.ping(detector.probe(), -1, 400);
        assertFalse(detector.evaluate(400).isAlarm());
        detector.ping(detector.probe(), 30, 500);
        assertEquals(LagDetector.Reason.PROBE_FAILURES, detector.evaluate(500).reason);
    }

    @Test public void failuresLeaveRollingWindow()
    {
        fastSettings(200, 2, 5, 20);
        calibrate();
        detector.ping(detector.probe(), -1, 400);
        detector.ping(detector.probe(), 30, 500);
        detector.evaluate(500);
        for (int i = 1; i <= 8; i++)
        {
            detector.tick(i * 600);
            detector.ping(detector.probe(), 30, i * 600);
            detector.evaluate(i * 600);
        }
        assertFalse(detector.evaluate(4800).isAlarm());
    }

    @Test public void singleConfirmationModeAlertsOnFirstHighPing()
    {
        fastSettings(200, 1, 20, 20);
        detector.ping(detector.probe(), 450, 100);
        assertEquals(LagDetector.Reason.HIGH_PING, detector.evaluate(100).reason);
    }

    @Test public void liveSettingsEnforceMinimums()
    {
        LagDetector.Settings settings = new LagDetector.Settings(0, 0, 0, true, 0, 0, true, 0, 0, 0);
        assertEquals(900, settings.stallMs);
        assertEquals(100, settings.pingThresholdMs);
        assertEquals(100, settings.probeDeadlineMs);
        assertEquals(1, settings.highPingSamples);
        assertEquals(1, settings.failurePercent);
        assertEquals(5, settings.failureWindow);
    }

    @Test public void distinguishesLocalClientPauseFromMissingServerTicks()
    {
        detector.clientTick(100);
        assertEquals(LagDetector.Reason.CLIENT_STALL, detector.evaluate(1600).reason);
        detector.clientTick(1610);
        assertEquals(LagDetector.Reason.TICK_STALL, detector.evaluate(1620).reason);
    }

    @Test public void confirmedDisconnectInvalidatesDelayedProbe()
    {
        fastSettings(200, 2, 20, 20);
        calibrate();
        LagDetector.Probe pending = detector.probe();
        detector.beginProbe(pending, 400);
        detector.evaluate(600);
        detector.connectionLost();
        detector.ping(pending, -1, 2400);
        assertEquals(LagDetector.Mode.IDLE, detector.evaluate(2500).mode);
        assertFalse(detector.evaluate(2500).isAlarm());
    }

    @Test public void soundOrColorChangesDoNotResetCalibration()
    {
        fastSettings(200, 2, 20, 20);
        calibrate();
        fastSettings(200, 2, 20, 20);
        detector.beginProbe(detector.probe(), 400);
        assertEquals(LagDetector.Reason.PROBE_DELAY, detector.evaluate(600).reason);
    }

    private void trainAutomatic(int ping)
    {
        detector.configure(LagDetector.Settings.automatic());
        detector.stop();
        detector.loggedIn(301, 0);
        for (int i = 1; i <= 6; i++)
        {
            detector.tick(i * 600);
            detector.ping(detector.probe(), ping, i * 600);
        }
    }

    @Test public void automaticModeAcceptsStable250msAndAdaptsDeadline()
    {
        trainAutomatic(250);
        assertFalse(detector.evaluate(3600).isAlarm());
        assertEquals(250, detector.evaluate(3600).normalPingMs);
        assertEquals(750, detector.evaluate(3600).deadlineMs);
        detector.beginProbe(detector.probe(), 3700);
        assertFalse(detector.evaluate(4449).isAlarm());
        assertEquals(LagDetector.Reason.PROBE_DELAY, detector.evaluate(4450).reason);
    }

    @Test public void automaticModeDetectsLargeRelativeJump()
    {
        trainAutomatic(250);
        detector.ping(detector.probe(), 600, 3700);
        assertFalse(detector.evaluate(3700).isAlarm());
        detector.ping(detector.probe(), 600, 4000);
        assertEquals(LagDetector.Reason.HIGH_PING, detector.evaluate(4000).reason);
        assertEquals(250, detector.evaluate(4000).normalPingMs);
    }

    @Test public void automaticModeStillWarnsAboutExtremeInitialLatency()
    {
        trainAutomatic(1500);
        assertEquals(LagDetector.Reason.HIGH_PING, detector.evaluate(3600).reason);
    }

    @Test public void automaticModeFallsBackAndRearmsAfterBlockedIcmp()
    {
        trainAutomatic(30);
        for (int i = 7; i <= 12; i++)
        {
            detector.tick(i * 600);
            detector.ping(detector.probe(), -1, i * 600);
            detector.evaluate(i * 600);
        }
        assertFalse(detector.evaluate(7200).isAlarm());
        assertEquals("Ping unavailable; retrying", detector.evaluate(7200).pingStatus);
        assertEquals(30000, detector.probeDelay());
        for (int i = 13; i <= 18; i++)
        {
            detector.tick(i * 600);
            detector.ping(detector.probe(), 80, i * 600);
            detector.evaluate(i * 600);
        }
        assertFalse(detector.evaluate(10800).isAlarm());
        assertEquals("Active", detector.evaluate(10800).pingStatus);
        assertEquals(80, detector.evaluate(10800).normalPingMs);
    }
}

package com.lagalarm;

import org.junit.Test;
import static org.junit.Assert.*;

public class PingBaselineTest
{
    private PingBaseline trained(int rtt)
    {
        PingBaseline baseline = new PingBaseline();
        baseline.reset();
        for (int i = 0; i < 5; i++) { baseline.record(rtt, true, i * 1000); }
        return baseline;
    }

    @Test public void stableHighPingGetsItsOwnBaseline()
    {
        PingBaseline baseline = trained(250);
        assertTrue(baseline.isAvailable());
        assertEquals(250, baseline.normalPing());
        assertEquals(500, baseline.highThreshold());
        assertEquals(750, baseline.deadline());
    }

    @Test public void smallAbsoluteIncreaseIsNotAlarmWorthy()
    {
        PingBaseline baseline = trained(10);
        assertEquals(200, baseline.highThreshold());
        assertEquals(400, baseline.deadline());
    }

    @Test public void egregiousLatencyIsNotNormalizedAway()
    {
        PingBaseline baseline = trained(1500);
        assertEquals(1000, baseline.highThreshold());
    }

    @Test public void sustainedSpikeDoesNotBecomeTheNewNormal()
    {
        PingBaseline baseline = trained(30);
        for (int i = 5; i < 100; i++) { baseline.record(800, true, i * 1000); }
        assertEquals(30, baseline.normalPing());
        assertEquals(200, baseline.highThreshold());
    }

    @Test public void initialOutlierDoesNotDominateMedian()
    {
        PingBaseline baseline = new PingBaseline();
        baseline.reset();
        for (int value : new int[]{1200, 30, 35, 25, 30}) { baseline.record(value, true, 0); }
        assertEquals(30, baseline.normalPing());
    }

    @Test public void failuresBackOffButDoNotPermanentlyDisable()
    {
        PingBaseline baseline = trained(30);
        int[] waits = {1000, 2000, 4000, 8000, 16000, 30000, 30000};
        for (int i = 0; i < waits.length; i++)
        {
            baseline.record(-1, true, 5000 + i * 1000);
            assertEquals(waits[i], baseline.retryDelay());
        }
        assertFalse(baseline.isAvailable());
        for (int i = 0; i < 5; i++) { baseline.record(70, true, 20000 + i * 1000); }
        assertTrue(baseline.isAvailable());
        assertEquals(70, baseline.normalPing());
        assertEquals(1000, baseline.retryDelay());
    }

    @Test public void neverWorkingIcmpCannotCalibrate()
    {
        PingBaseline baseline = new PingBaseline();
        baseline.reset();
        for (int i = 0; i < 100; i++) { baseline.record(-1, true, i * 1000); }
        assertFalse(baseline.isAvailable());
        assertEquals(-1, baseline.normalPing());
        assertEquals(30000, baseline.retryDelay());
    }

    @Test public void failingGameUpdatesDoNotTrainBaseline()
    {
        PingBaseline baseline = trained(30);
        for (int i = 0; i < 100; i++) { baseline.record(150, false, i * 1000); }
        assertEquals(30, baseline.normalPing());
    }

    @Test public void fastConfirmationBurstIsBounded()
    {
        PingBaseline baseline = trained(30);
        baseline.record(800, true, 5000);
        assertEquals(250, baseline.retryDelay());
        for (int i = 1; i <= 8; i++) { baseline.record(800, true, 5000 + i * 250); }
        assertEquals(1000, baseline.retryDelay());
        baseline.record(800, true, 34000);
        assertEquals(1000, baseline.retryDelay());
        baseline.record(800, true, 35000);
        assertEquals(250, baseline.retryDelay());
    }
}

